import {draftStandard,releaseStandard,isReleasedStandard} from './standards.mjs';
import {createPresetProject} from './presets.mjs';
import {fieldGroups,listSchemas,modules} from './modules.mjs';
import {esc} from './document.mjs';

export function setupStandards({getTemplates,getProjects,openSource,save,notify,onSaved}){
  const dialog=document.querySelector('#standards-dialog');
  let draft=null,dirty=false,busy=false;
  const label=key=>Object.values(fieldGroups).flat().find(f=>f[0]===key)?.[1]||key;
  const close=()=>{if(busy)return;if(dirty&&!confirm('Discard this unsaved standard draft?'))return;draft=null;dirty=false;dialog.close();};
  const input=(value,attrs='')=>`<input ${attrs} value="${esc(value)}">`;
  function render(){
    const legacy=getProjects().filter(p=>p.preset==='hatco');const records=getTemplates().filter(t=>t.type==='company');
    dialog.innerHTML=`<button class="dialog-close" type="button" data-standard-close aria-label="Close">×</button><span class="eyebrow">COMPANY STANDARDS</span><h2>Versioned company library</h2><p>Standards belong to your account. Projects keep an independent copy pinned to the version applied. Publishing here records an internal baseline; it does not approve a project BEP.</p>${draft?editor():`<div class="standard-toolbar"><button class="button primary" data-standard-new>New from HATCO baseline</button><label>Or capture an existing project<select id="standard-project"><option value="">Choose a source project</option>${getProjects().map(p=>`<option value="${esc(p.id)}">${esc(p.fields.projectName)}</option>`).join('')}</select></label><button class="button secondary" data-standard-capture>Capture company content</button></div><div class="legacy-standard-sources">${legacy.length?'<h3>Retained company sources</h3><p>Earlier company BEPs are kept here with their original data and files. Capture one above to release a standard version.</p>':''}${legacy.map(p=>`<button class="button ghost" data-standard-source="${esc(p.id)}">Open retained source: ${esc(p.fields.projectName)}</button>`).join('')}</div><div class="template-grid">${records.map(t=>`<article class="template-card company"><span class="template-badge">${isReleasedStandard(t)?'RELEASED · IMMUTABLE':'LEGACY · UNVERSIONED'}</span><h3>${esc(t.name)}</h3><p>Version ${esc(t.version)} · ${esc(t.sourceReference||'No source recorded')}</p><p>${esc(t.data.standard?.releaseNotes||t.description)}</p><button class="button secondary" data-standard-open="${esc(t.id)}">${isReleasedStandard(t)?'View / create next version':'Review & release a version'}</button></article>`).join('')||'<p>No company versions yet. Start from the supplied HATCO baseline or capture company procedures from an existing project.</p>'}</div>`}`;
    dialog.querySelector('[data-standard-close]').onclick=close;
    dialog.querySelector('[data-standard-new]')?.addEventListener('click',()=>start(createPresetProject('hatco'),{name:'HATCO Company BIM Standard',sourceReference:'HATCO internal BIM standard — supplied BEP reference',version:'1.0'}));
    dialog.querySelector('[data-standard-capture]')?.addEventListener('click',()=>{const p=getProjects().find(p=>p.id===dialog.querySelector('#standard-project').value);if(!p){notify('Choose a source project first.');return;}start(p,{name:`${p.fields.contractor||'Company'} BIM Standard`,sourceReference:p.fields.documentCode||'',version:'1.0'});});
    dialog.querySelectorAll('[data-standard-open]').forEach(b=>b.onclick=()=>{const t=records.find(t=>t.id===b.dataset.standardOpen);start(t);});
    dialog.querySelectorAll('[data-standard-source]').forEach(b=>b.onclick=()=>{dialog.close();openSource(b.dataset.standardSource);});
    if(!draft)return;
    dialog.querySelector('[data-draft-back]').onclick=()=>{if(dirty&&!confirm('Discard this unsaved standard draft?'))return;draft=null;dirty=false;render();};
    dialog.querySelectorAll('[data-meta]').forEach(el=>el.oninput=()=>{draft[el.dataset.meta]=el.value;dirty=true;});
    dialog.querySelector('[name="releaseNotes"]').oninput=e=>{draft.data.standard.releaseNotes=e.target.value;dirty=true;};
    dialog.querySelectorAll('[data-standard-field]').forEach(el=>el.oninput=()=>{draft.data.fields[el.dataset.standardField]=el.value;dirty=true;});
    dialog.querySelectorAll('[data-standard-note]').forEach(el=>el.oninput=()=>{draft.data.notes[el.dataset.standardNote]=el.value;dirty=true;});
    dialog.querySelectorAll('[data-standard-cell]').forEach(el=>el.oninput=()=>{draft.data.lists[el.dataset.table][Number(el.dataset.row)][el.dataset.standardCell]=el.value;dirty=true;});
    dialog.querySelectorAll('[data-standard-add]').forEach(el=>el.onclick=()=>{draft.data.lists[el.dataset.standardAdd].push({});dirty=true;render();});
    dialog.querySelectorAll('[data-standard-remove]').forEach(el=>el.onclick=()=>{draft.data.lists[el.dataset.standardRemove].splice(Number(el.dataset.row),1);dirty=true;render();});
    dialog.querySelector('form').onsubmit=async e=>{
      e.preventDefault();if(busy)return;
      try{const released=releaseStandard(draft,getTemplates());busy=true;dialog.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);await save(released);draft=null;dirty=false;onSaved(released);render();notify('Company standard released. Existing projects keep their pinned version.');}
      catch(error){notify(error.message);dialog.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=false);}
      finally{busy=false;}
    };
  }
  function start(source,meta={}){draft=draftStandard(source,meta);dirty=false;render();}
  function editor(){return `<form><div class="field-grid"><label class="field">Name${input(draft.name,'data-meta="name" required maxlength="160"')}</label><label class="field">New version${input(draft.version,'data-meta="version" required maxlength="30" placeholder="e.g. 1.1"')}</label><label class="field wide">Source reference${input(draft.sourceReference,'data-meta="sourceReference" required maxlength="300"')}</label><label class="field wide">Description<textarea data-meta="description" rows="2">${esc(draft.description)}</textarea></label><label class="field wide">Release notes<textarea name="releaseNotes" required rows="3">${esc(draft.data.standard.releaseNotes)}</textarea></label></div><p>This is an unsaved draft of ${draft.data.standard.parentId?'a new version. The released parent stays unchanged.':'a new standard.'} Review project-specific wording before release. Closing discards the draft.</p><details open><summary>Company settings</summary><div class="field-grid">${Object.entries(draft.data.fields||{}).map(([k,v])=>`<label class="field">${esc(label(k))}<textarea data-standard-field="${esc(k)}" rows="2">${esc(v)}</textarea></label>`).join('')}</div></details><details><summary>Procedures</summary>${Object.entries(draft.data.notes||{}).map(([k,v])=>`<label>${esc(modules.find(m=>m.id===k)?.title||k)}<textarea data-standard-note="${esc(k)}" rows="5">${esc(v)}</textarea></label>`).join('')}</details><details><summary>Reusable schedules</summary>${Object.entries(draft.data.lists||{}).filter(([k])=>listSchemas[k]).map(([k,rows])=>`<details><summary>${esc(listSchemas[k].label)} · ${rows.length} rows</summary><div class="table-scroll"><table class="editor-table"><thead><tr>${listSchemas[k].columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th>Remove</th></tr></thead><tbody>${rows.map((row,i)=>`<tr>${listSchemas[k].columns.map(([col])=>`<td>${input(row[col]||'',`data-table="${k}" data-row="${i}" data-standard-cell="${col}"`)}</td>`).join('')}<td><button type="button" data-standard-remove="${k}" data-row="${i}">×</button></td></tr>`).join('')}</tbody></table></div><button class="button secondary" type="button" data-standard-add="${k}">+ Add row</button></details>`).join('')}</details><div class="dialog-actions"><button type="button" class="button ghost" data-draft-back>Back to versions</button><button type="submit" class="button primary">Release immutable version</button></div></form>`;}
  dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
  return ()=>{draft=null;dirty=false;render();dialog.showModal();};
}
